/*
 * Compute the IPv4 header checksum (RFC 791 / RFC 1071) over 'len'
 * bytes at 'hdr'. The checksum field in the header is already zero.
 * Return the 16-bit value in network byte order, ready to store
 * directly into iph->check.
 *
 * 'hdr' may be at any alignment (e.g. 14 bytes into an Ethernet frame).
 */
uint16_t ip_checksum(const void *hdr, size_t len);

solution:
#include <arpa/inet.h>

uint16_t ip_checksum(const void *hdr, size_t len)
{
    const uint8_t *p = hdr;
    uint32_t sum = 0;

    while (len > 1) {                       /* sum big-endian 16-bit words */
        sum += (uint32_t)p[0] << 8 | p[1];
        p += 2;
        len -= 2;
    }
    if (len)                                /* odd trailing byte, zero-padded */
        sum += (uint32_t)p[0] << 8;

    while (sum >> 16)                       /* fold carries back in */
        sum = (sum & 0xffff) + (sum >> 16);

    return htons((uint16_t)~sum);           /* one's complement of the sum */
}

