/*
 * Return x with its bit order reversed: bit 0 <-> bit 31, bit 1 <-> bit 30...
 *   rev32(0x00000001) == 0x80000000
 *   rev32(0x12345678) == 0x1E6A2C48
 *
 * Use case: an SPI/serial peripheral that shifts LSB-first while the
 * device datasheet documents MSB-first frames.
 */
uint32_t rev32(uint32_t x);

solution:
/* Simple: 32 iterations */
uint32_t rev32_loop(uint32_t x)
{
    uint32_t r = 0;

    for (int i = 0; i < 32; i++) {
        r = (r << 1) | (x & 1);
        x >>= 1;
    }
    return r;
}

/* Divide and conquer: swap adjacent bits, pairs, nibbles, bytes, halves */
uint32_t rev32(uint32_t x)
{
    x = ((x >> 1) & 0x55555555u) | ((x & 0x55555555u) << 1);
    x = ((x >> 2) & 0x33333333u) | ((x & 0x33333333u) << 2);
    x = ((x >> 4) & 0x0F0F0F0Fu) | ((x & 0x0F0F0F0Fu) << 4);
    x = ((x >> 8) & 0x00FF00FFu) | ((x & 0x00FF00FFu) << 8);
    return (x >> 16) | (x << 16);
}

