#define RB_SIZE 256                 /* must be a power of two */

struct ring {
    _Atomic uint32_t head;          /* written only by the producer */
    _Atomic uint32_t tail;          /* written only by the consumer */
    uint8_t buf[RB_SIZE];
};

/* Producer: UART RX ISR. Return false (drop the byte) if full. */
bool rb_push(struct ring *r, uint8_t b);

/* Consumer: main loop / thread. Return false if empty. */
bool rb_pop(struct ring *r, uint8_t *b);

solution:
bool rb_push(struct ring *r, uint8_t b)
{
    uint32_t head = atomic_load_explicit(&r->head, memory_order_relaxed);
    uint32_t tail = atomic_load_explicit(&r->tail, memory_order_acquire);

    if (head - tail == RB_SIZE)             /* full */
        return false;
    r->buf[head & (RB_SIZE - 1)] = b;
    /* publish the data before the new head becomes visible */
    atomic_store_explicit(&r->head, head + 1, memory_order_release);
    return true;
}

bool rb_pop(struct ring *r, uint8_t *b)
{
    uint32_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
    uint32_t head = atomic_load_explicit(&r->head, memory_order_acquire);

    if (head == tail)                       /* empty */
        return false;
    *b = r->buf[tail & (RB_SIZE - 1)];
    /* finish reading the slot before handing it back */
    atomic_store_explicit(&r->tail, tail + 1, memory_order_release);
    return true;
}
